import React from 'react';
import { getDisplayName } from '../utils/userSession';

export const ParticipantsPanel = ({ participants = [] }) => {
  return (
    <div className="p-4">
      <div className="mb-4">
        <h3 className="text-white font-semibold mb-2">
          Participants ({participants.length})
        </h3>
      </div>

      {participants.length === 0 ? (
        <div className="text-center py-8 text-gray-400">
          <p>No participants</p>
        </div>
      ) : (
        <div className="space-y-3">
          {participants.map((participant, idx) => (
            <div
              key={idx}
              className="flex items-center gap-3 bg-gray-800 rounded-lg p-3"
            >
              <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white font-semibold ${
                participant.isAI ? 'bg-purple-500' : 'bg-blue-500'
              }`}>
                {participant.isAI ? '🤖' : getDisplayName(participant.userId).charAt(0).toUpperCase()}
              </div>
              <div className="flex-1">
                <p className="text-white font-medium">
                  {participant.isAI ? participant.userId : getDisplayName(participant.userId)}
                </p>
                <p className="text-xs text-gray-400">
                  {participant.isAI ? '🎓 AI Tutor' : participant.isHost ? '👑 Host (You)' : 'Participant'}
                </p>
              </div>
              <div className="flex gap-2">
                {!participant.isAI && (
                  <>
                    {participant.isMuted ? (
                      <span className="text-red-400" title="Muted">🔇</span>
                    ) : (
                      <span className="text-green-400" title="Unmuted">🎤</span>
                    )}
                    {participant.isVideoOff ? (
                      <span className="text-red-400" title="Camera off">📵</span>
                    ) : (
                      <span className="text-green-400" title="Camera on">📹</span>
                    )}
                  </>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};
